package org.securemail.ui;

import com.google.gson.*;
import javafx.scene.Node;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import java.util.*;
import static org.securemail.ui.CommunityUi.*;

/** Organizations are server-owned entities. No local approval, membership or role authority. */
final class OrganizationsView {
  private final CommunityUi api;private final Label status=label("");private final BorderPane root=new BorderPane();private final ListView<JsonObject> catalog=list("Организации не найдены");private final VBox details=new VBox(10);private JsonObject selected;
  OrganizationsView(CommunityUi api){this.api=api;root.setId("organizations-page");TextField search=field("Найти организацию");List<JsonObject> all=new ArrayList<>();search.textProperty().addListener((o,a,b)->catalog.getItems().setAll(all.stream().filter(v->title(v).toLowerCase(Locale.ROOT).contains(b.toLowerCase(Locale.ROOT))).toList()));Button refresh=button("Обновить",()->refresh(all));VBox header=card(heading("Организации"),actions(search,refresh,button("Подать заявку",this::application)),status);root.setTop(header);catalog.setPrefWidth(240);catalog.getSelectionModel().selectedItemProperty().addListener((o,a,b)->{if(b!=null){selected=b;load();}});SplitPane split=new SplitPane(catalog,scroll(details));split.setDividerPositions(.3);root.setCenter(split);root.widthProperty().addListener((o,a,b)->split.setOrientation(b.doubleValue()<700?javafx.geometry.Orientation.VERTICAL:javafx.geometry.Orientation.HORIZONTAL));refresh(all);}
  Node node(){return root;}
  private void refresh(List<JsonObject> all){api.call("org.list",obj(),status,data->{all.clear();all.addAll(items(data,data.has("organizations")?"organizations":"items"));catalog.getItems().setAll(all);});}
  private String id(){return str(selected,"id");}
  private void load(){api.call("org.get",obj("id",id()),status,value->{selected=value.has("organization")?value.getAsJsonObject("organization"):value;details.getChildren().clear();TabPane tabs=new TabPane();tabs.setTabClosingPolicy(TabPane.TabClosingPolicy.UNAVAILABLE);for(String name:List.of("Главная","Новости","События","Состав","Библиотека","Управление")){if(name.equals("Управление")&&!RoleBuilder.join(array(selected,"permissions")).matches(".*(ORG_MANAGE|ROLES_MANAGE|MEMBERS_MANAGE).*"))continue;VBox pane=new VBox(10);Tab tab=new Tab(name,scroll(pane));tab.setOnSelectionChanged(e->{if(tab.isSelected())fill(name,pane);});tabs.getTabs().add(tab);}details.getChildren().addAll(heading(title(selected)),tabs);VBox.setVgrow(tabs,Priority.ALWAYS);fill("Главная",(VBox)((ScrollPane)tabs.getTabs().getFirst().getContent()).getContent());});}
  private void fill(String section,VBox pane){pane.getChildren().clear();switch(section){case "Главная"->pane.getChildren().addAll(label(str(selected,"description")),label(str(selected,"purpose")),label(str(selected,"city").isBlank()?"Город не указан":str(selected,"city")),actions(button("Вступить",()->api.call("org.join",obj("id",id()),status,r->load())),button("Подать заявку на вступление",()->api.call("org.join.request",obj("id",id()),status,r->load()))));case "Состав"->{ListView<JsonObject> members=list("Нет доступных участников");String[] after={""};members.setCellFactory(v->new ListCell<>(){protected void updateItem(JsonObject member,boolean empty){super.updateItem(member,empty);setText(null);if(empty||member==null)setGraphic(null);else{List<String> roleNames=new ArrayList<>();for(JsonObject role:items(member,"roles"))roleNames.add(str(role,"name"));setGraphic(new VBox(4,label(str(member,"nickname")),label(String.join(" · ",roleNames))));}}});pane.getChildren().add(members);java.util.function.Consumer<Boolean> load=more->api.call("org.members.list",obj("id",id(),"after",more?after[0]:""),status,r->{if(!more)members.getItems().clear();members.getItems().addAll(items(r,r.has("members")?"members":"items"));after[0]=str(r,"nextAfter");});pane.getChildren().add(button("Ещё участники",()->{if(!after[0].isEmpty()&&members.getItems().size()<500)load.accept(true);}));load.accept(false);}case "Новости"->pane.getChildren().add(new NewsView(api,"ORGANIZATIONS",id()).node());case "События"->pane.getChildren().add(new NewsView(api,"EVENTS",id()).node());case "Библиотека"->pane.getChildren().add(new KnowledgeLibraryView(api,id()).node());default->management(pane);}}
  private void application(){TextField name=field("Название"),purpose=field("Назначение");CityPicker city=new CityPicker(api,"");TextArea description=new TextArea();description.setPromptText("Описание организации");description.setWrapText(true);description.setPrefRowCount(4);ComboBox<String> policy=new ComboBox<>();policy.getItems().setAll("Открытое вступление","По заявке","По приглашению");policy.getSelectionModel().selectFirst();final String[] emblem={""};Label emblemState=label("Эмблема не выбрана");Button chooseEmblem=button("Выбрать эмблему",()->{InWindowFileChooser chooser=new InWindowFileChooser();chooser.setTitle("Эмблема организации");java.io.File file=chooser.showOpenDialog((javafx.stage.Stage)root.getScene().getWindow());if(file!=null)api.task(()->{java.nio.file.Path path=file.toPath();if(java.nio.file.Files.isSymbolicLink(path)||java.nio.file.Files.size(path)>500000)throw new java.io.IOException();byte[] raw=java.nio.file.Files.readAllBytes(path);try{return Base64.getEncoder().encodeToString(raw);}finally{Arrays.fill(raw,(byte)0);}},status,result->{emblem[0]=result;emblemState.setText("Эмблема выбрана. Сервер проверит формат и удалит метаданные.");});});VBox form=card(heading("Заявка на организацию"),name,description,purpose,city.node(),policy,chooseEmblem,emblemState,button("Отправить на одобрение",()->api.call("org.applications.create",obj("name",name.getText(),"description",description.getText(),"purpose",purpose.getText(),"city",city.id(),"emblemBase64",emblem[0],"joinPolicy",switch(policy.getSelectionModel().getSelectedIndex()){case 1->"REQUEST";case 2->"INVITE";default->"OPEN";}),status,r->{status.setText("Заявка направлена администрации. Организация появится после одобрения.");details.getChildren().clear();})));details.getChildren().setAll(form);}
  private void management(VBox pane){TextField user=field("Криптографический идентификатор участника"),role=field("Идентификатор роли");ComboBox<JsonObject> users=choice("Выберите участника"),roles=choice("Выберите роль");users.setOnAction(e->{JsonObject chosen=users.getValue();if(chosen!=null)user.setText(str(chosen,"identity"));});roles.setOnAction(e->{JsonObject chosen=roles.getValue();if(chosen!=null)role.setText(str(chosen,"id"));});api.call("org.members.list",obj("id",id()),null,r->users.getItems().setAll(items(r,"items")));api.call("org.roles.list",obj("scope","ORG:"+id(),"limit",30),null,r->roles.getItems().setAll(items(r,"items")));ListView<JsonObject> requests=list("Нет доступных заявок на вступление");Runnable loadRequests=()->api.call("org.join.requests",obj("org",id()),status,r->CommunityUi.fill(requests,r,"items"));pane.getChildren().addAll(label("Сервер проверяет полномочия перед каждым изменением."),users,roles,fold("Участник по проверенному идентификатору",card(user,role)),actions(button("Пригласить",()->api.privileged("org.invite",obj("org",id(),"user",user.getText()),status,r->load())),button("Удалить участника",()->api.privileged("org.members.remove",obj("org",id(),"user",user.getText()),status,r->load())),button("Назначить роль",()->api.privileged("admin.roles.assign",obj("role",role.getText(),"user",user.getText()),status,r->load())),button("Отозвать роль",()->api.privileged("admin.roles.revoke",obj("role",role.getText(),"user",user.getText()),status,r->load()))),fold("Заявки на вступление",card(requests,actions(button("Обновить заявки",loadRequests),button("Принять участника",()->decideJoin(requests,true,loadRequests)),button("Отклонить заявку",()->decideJoin(requests,false,loadRequests))))),new RoleBuilder(api,"ORG:"+id(),status).node(),organizationSettings());loadRequests.run();}
  private Node organizationSettings(){TextField name=field("Название организации");name.setText(str(selected,"name"));TextArea description=new TextArea(str(selected,"description"));description.setWrapText(true);description.setPrefRowCount(4);CityPicker city=new CityPicker(api,str(selected,"city"));ComboBox<String> joining=new ComboBox<>();joining.getItems().setAll("Открытое вступление","По заявке","По приглашению");joining.getSelectionModel().select(switch(str(selected,"joinPolicy")){case "REQUEST"->1;case "INVITE"->2;default->0;});return fold("Настройки организации",card(name,description,city.node(),joining,button("Сохранить организацию",()->api.privileged("org.update",obj("id",id(),"revision",number(selected,"revision"),"name",name.getText(),"description",description.getText(),"city",city.id(),"emblemBase64",str(selected,"emblemBase64"),"joinPolicy",switch(joining.getSelectionModel().getSelectedIndex()){case 1->"REQUEST";case 2->"INVITE";default->"OPEN";}),status,r->load()))));}
  private void decideJoin(ListView<JsonObject> requests,boolean approve,Runnable refresh){JsonObject request=requests.getSelectionModel().getSelectedItem();if(request!=null)api.privileged("org.join.decide",obj("org",id(),"user",str(request,"identity"),"approve",approve),status,r->refresh.run());}
}
